            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
        }
    }

    @Override
    public ResultadoEntrega calcular(BigDecimal pesoKg) {
        return new ResultadoEntrega(new BigDecimal("18.00"), 0);
    }
}

